 public Long measurableLeaveSeconds(UUID tenant,UUID company,UUID employee,LocalDate date,Instant from,Instant to){if(date==null||from==null||to==null||!to.isAfter(from))throw WorkforceException.invalid();var emp=employees.find(tenant,employee).orElseThrow(WorkforceException::missing);if(date.isBefore(emp.hireDate())||emp.leaveDate()!=null&&date.isAfter(emp.leaveDate())||!company.equals(policyRepository.company(tenant,employee,date)))return 0L;var p=policies.resolve(tenant,company,employee,date);var ids=approvals.bounded(approvals.scheduleIds(tenant,null,company,date,date,employee));var plans=new ArrayList<Plan>();for(var item:schedules.scoped(tenant,ids))if(item.schedule().status().equals("scheduled")&&!schedules.deleted(tenant,item.schedule().id()))plans.add(plan(item.schedule()));if(plans.isEmpty()){var a=p.arrangement();if(a==null)return null;if(p.sourceStoreId()!=null&&(repository.calendar(tenant,p.sourceStoreId(),date).stream().anyMatch(e->e.enabled()&&e.kind().equals("store_rest"))||repository.restSwaps(tenant,p.sourceStoreId(),employee,date).stream().anyMatch(e->e.restDate().equals(date))))return 0L;if(!a.weekdays().contains(date.getDayOfWeek().getValue()))return 0L;var begin=date.atTime(a.startTime()).atZone(ZoneId.of(p.timezone())).toInstant();var windows=new ArrayList<com.rpb.reservation.workforce.attendance.AttendanceDtos.Interval>();if(a.unpaidBreakMinutes()>0){if(a.unpaidBreakStartOffsetMinutes()==null)return null;var ba=begin.plusSeconds(a.unpaidBreakStartOffsetMinutes()*60L);windows.add(new com.rpb.reservation.workforce.attendance.AttendanceDtos.Interval(ba,ba.plusSeconds(a.unpaidBreakMinutes()*60L)));}plans.add(new Plan(begin,begin.plusSeconds((a.standardWorkMinutes()+a.unpaidBreakMinutes())*60L),a.standardWorkMinutes()*60L,a.unpaidBreakMinutes()*60L,windows));}long seconds=0;Instant previous=null;for(var plan:plans.stream().sorted(Comparator.comparing(Plan::start)).toList()){if(previous!=null&&plan.start().isBefore(previous))return null;previous=plan.end();var a=from.isAfter(plan.start())?from:plan.start();var b=to.isBefore(plan.end())?to:plan.end();if(!b.isAfter(a))continue;if(plan.breaks()>0&&plan.windows().isEmpty()){if(a.equals(plan.start())&&b.equals(plan.end()))seconds+=plan.standard();else return null;}else seconds+=com.rpb.reservation.workforce.attendance.BreakCalculator.subtract(a,b,plan.windows()).stream().mapToLong(i->Duration.between(i.start(),i.end()).getSeconds()).sum();}return seconds;}
 public MonthPage month(CurrentActor actor,UUID store,YearMonth month,UUID employee,String search,UUID position,int limit,int offset){access.enter(actor,store);if(month==null||limit<1||limit>100||offset<0||search!=null&&search.length()>100)throw WorkforceException.invalid();boolean manager=access.managedStores(actor).contains(store);UUID self=manager?null:employees.byAccount(actor.tenantId(),actor.actorId()).orElseThrow(WorkforceException::forbidden).id();if(self!=null&&employee!=null&&!self.equals(employee))throw WorkforceException.forbidden();var candidates=repository.employees(actor.tenantId(),store,month.atDay(1),month.atEndOfMonth());var facts=employees.findAll(actor.tenantId(),candidates);var filtered=candidates.stream().map(facts::get).filter(Objects::nonNull).filter(e->self==null||self.equals(e.id())).filter(e->employee==null||employee.equals(e.id())).filter(e->position==null||position.equals(e.positionId())).filter(e->search==null||search.isBlank()||(e.name()+" "+e.employeeNo()).toLowerCase(Locale.ROOT).contains(search.toLowerCase(Locale.ROOT))).toList();var rows=new ArrayList<EmployeeMonth>();for(var e:filtered.stream().skip(offset).limit(limit).toList()){var company=policyRepository.store(actor.tenantId(),store).companyId();var days=new ArrayList<EffectiveDay>();for(var date=month.atDay(1);!date.isAfter(month.atEndOfMonth());date=date.plusDays(1)){if(date.isBefore(e.hireDate())||(e.leaveDate()!=null&&date.isAfter(e.leaveDate())))days.add(new EffectiveDay(null,store,date,"clock","outside_employment","not_applicable","",0,null,null,0,0,0,Map.of(),List.of()));else if(!company.equals(policyRepository.company(actor.tenantId(),e.id(),date)))days.add(restricted(date));else{var day=evaluate(actor.tenantId(),company,e.id(),date,false);days.add(day.storeId()!=null&&!store.equals(day.storeId())||day.snapshot().containsKey("storeIds")&&((List<?>)day.snapshot().get("storeIds")).stream().anyMatch(x->!store.equals(x))?restricted(date):publicDay(day));}}Long work=days.stream().allMatch(d->Set.of("not_applicable","outside_employment").contains(d.state()))?null:days.stream().anyMatch(d->d.workSeconds()==null&&!Set.of("not_applicable","outside_employment","future").contains(d.state()))?null:days.stream().filter(d->d.workSeconds()!=null).mapToLong(EffectiveDay::workSeconds).sum();var row=new EmployeeMonth(e.id(),e.employeeNo(),e.name(),List.copyOf(days),new MonthTotals(work,days.stream().mapToLong(EffectiveDay::paidLeaveSeconds).sum(),days.stream().mapToLong(EffectiveDay::unpaidLeaveSeconds).sum(),days.stream().mapToLong(d->((Number)d.snapshot().getOrDefault("absenceSeconds",0L)).longValue()).sum(),days.stream().mapToLong(EffectiveDay::extraSeconds).sum(),days.stream().mapToLong(this::pendingItems).sum()));if(overtime!=null){var context=capture(actor.tenantId(),company,e.id(),month.atDay(1).with(java.time.temporal.TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY)),month.atEndOfMonth());row=overtime.project(actor,store,company,row,month,context);}rows.add(row);}return new MonthPage(month,rows,filtered.size(),limit,offset,manager);}
 private EffectiveDay restricted(LocalDate date){return new EffectiveDay(null,null,date,"clock","pending","not_applicable","",0,null,null,0,0,0,Map.of(),List.of("SCOPE_RESTRICTED"));}
 private List<Map<String,Object>> exceptionSummaries(Map<String,Object> snapshot){var result=new ArrayList<Map<String,Object>>();var seen=new HashSet<UUID>();Object raw=snapshot.get("exceptions");if(raw instanceof List<?> items)for(var item:items){IntervalException e=item instanceof IntervalException x?x:json.read(json.write(item),IntervalException.class);if(Set.of("rejected","cancelled","withdrawn").contains(e.status()))continue;seen.add(e.id());result.add(exceptionSummary(e.kind(),e.typeName(),e.status()));}for(var key:List.of("clockSources","scheduleSources"))if(snapshot.get(key) instanceof List<?> sources)for(var item:sources){var source=item instanceof ApprovalDtos.ApprovalSource x?x:json.read(json.write(item),ApprovalDtos.ApprovalSource.class);for(var l:source.leaves())if(!Set.of("rejected","cancelled","withdrawn").contains(l.status())&&seen.add(l.id()))result.add(exceptionSummary("leave",l.typeName(),l.status()));}return List.copyOf(result);}
 private Map<String,Object> exceptionSummary(String kind,String name,String status){var item=new LinkedHashMap<String,Object>();item.put("kind",kind);item.put("typeName",name);item.put("status",status);return item;}
 private long pendingItems(EffectiveDay day){var summaries=day.snapshot().get("exceptionSummaries") instanceof List<?> list?list:exceptionSummaries(day.snapshot());long requests=summaries.stream().filter(e->e instanceof Map<?,?>).map(e->(Map<?,?>)e).filter(e->Set.of("pending","cancel_requested").contains(e.get("status"))).count();return requests+day.issues().stream().filter(i->!i.equals("PENDING_REQUEST")||requests==0).count();}

 private EffectiveDay publicDay(EffectiveDay d){return new EffectiveDay(d.sourceId(),d.storeId(),d.workDate(),d.mode(),d.state(),d.sourceType(),d.sourceFingerprint(),d.version(),d.actualSeconds(),d.workSeconds(),d.paidLeaveSeconds(),d.unpaidLeaveSeconds(),d.extraSeconds(),Map.of("leaveBalanceState","unknown","timezone",d.snapshot().getOrDefault("timezone","UTC"),"companyId",String.valueOf(d.snapshot().get("companyId")),"absenceSeconds",((Number)d.snapshot().getOrDefault("absenceSeconds",0L)).longValue(),"exceptionSummaries",exceptionSummaries(d.snapshot()),"phase",d.snapshot().getOrDefault("phase","completed")),d.issues());}
 @Transactional public EffectiveDay review(CurrentActor actor,UUID store,UUID id,DayReviewWrite c){access.sourceWrite(actor);access.enter(actor,store);access.manage(actor,store);if(c==null||id==null||c.employeeId()==null||c.companyId()==null||c.workDate()==null||c.expectedVersion()==null||c.expectedVersion()<0||c.sourceFingerprint()==null||c.note()==null||c.note().isBlank()||c.note().trim().length()>500)throw WorkforceException.invalid();approvals.calendarLock(actor.tenantId(),store);employees.lock(c.employeeId());var employee=employees.find(actor.tenantId(),c.employeeId()).orElseThrow(WorkforceException::missing);var reviewBlock=ApprovalReviewerPolicy.block(access.isHeadOffice(actor),true,actor.actorId(),employee.accountId(),approvals.managerAccount(actor.tenantId(),employee.accountId()));if(reviewBlock!=null)throw new WorkforceException(reviewBlock,403);if(!schedules.hasStoreAssignment(actor.tenantId(),c.employeeId(),store)||!policyRepository.company(actor.tenantId(),c.employeeId(),c.workDate()).equals(c.companyId()))throw WorkforceException.missing();var next=evaluate(actor.tenantId(),c.companyId(),c.employeeId(),c.workDate(),true);if(!id.equals(next.sourceId())||!store.equals(next.storeId()))throw WorkforceException.missing();var old=repository.latest(actor.tenantId(),c.companyId(),c.employeeId(),c.workDate()).orElse(null);String note=c.note().trim();if(old!=null&&old.version()==c.expectedVersion()+1&&old.state().equals("human_valid")&&old.sourceFingerprint().equals(c.sourceFingerprint())&&old.sourceFingerprint().equals(next.sourceFingerprint())&&actor.actorId().toString().equals(old.snapshot().get("dayReviewerId"))&&note.equals(old.snapshot().get("dayReviewNote")))return publicDay(old);if((old==null?0:old.version())!=c.expectedVersion()||!next.sourceFingerprint().equals(c.sourceFingerprint()))throw WorkforceException.conflict();if(next.issues().isEmpty()||!next.issues().stream().allMatch(x->Set.of("CALENDAR_REVIEW_REQUIRED","WORKFORCE_MANAGER_ADMIN_REVIEW").contains(x))||!(next.snapshot().get("candidateWorkSeconds") instanceof Number))throw new WorkforceException("WORKFORCE_APPROVAL_BLOCKED",409);var snapshot=new LinkedHashMap<>(next.snapshot());snapshot.put("dayReviewerId",actor.actorId().toString());snapshot.put("dayReviewNote",note);snapshot.put("dayReviewedAt",clock.instant().toString());var saved=new EffectiveDay(id,store,next.workDate(),next.mode(),"human_valid",next.sourceType(),next.sourceFingerprint(),next.version(),next.actualSeconds(),((Number)snapshot.get("candidateWorkSeconds")).longValue(),next.paidLeaveSeconds(),next.unpaidLeaveSeconds(),next.extraSeconds(),snapshot,List.of());repository.save(actor.tenantId(),c.companyId(),c.employeeId(),actor.actorId(),saved);audit.changed(actor,store,"attendance.review",id,old,publicDay(saved));return publicDay(saved);}
 @Transactional public MonthPage refresh(CurrentActor actor,UUID store,RefreshWrite c){access.sourceWrite(actor);access.enter(actor,store);access.manage(actor,store);if(c==null||c.month()==null||c.employeeIds()==null||c.employeeIds().isEmpty()||c.employeeIds().size()>100||c.employeeIds().stream().anyMatch(Objects::isNull)||new HashSet<>(c.employeeIds()).size()!=c.employeeIds().size())throw WorkforceException.invalid();var valid=repository.employees(actor.tenantId(),store,c.month().atDay(1),c.month().atEndOfMonth());if(!valid.containsAll(c.employeeIds()))throw WorkforceException.missing();var company=policyRepository.store(actor.tenantId(),store).companyId();for(var employee:c.employeeIds().stream().sorted().toList()){approvals.calendarLock(actor.tenantId(),store);employees.lock(employee);var emp=employees.find(actor.tenantId(),employee).orElseThrow();for(var date=c.month().atDay(1);!date.isAfter(c.month().atEndOfMonth());date=date.plusDays(1)){if(date.isBefore(emp.hireDate())||(emp.leaveDate()!=null&&date.isAfter(emp.leaveDate()))||!company.equals(policyRepository.company(actor.tenantId(),employee,date)))continue;var next=evaluate(actor.tenantId(),company,employee,date,true);if(next.storeId()!=null&&!next.storeId().equals(store))continue;var old=repository.latest(actor.tenantId(),company,employee,date).orElse(null);if(old!=null&&old.sourceFingerprint().equals(next.sourceFingerprint())&&old.state().equals(next.state()))continue;repository.save(actor.tenantId(),company,employee,actor.actorId(),next);audit.changed(actor,store,"attendance.evaluate",next.sourceId(),old,publicDay(next));}}return month(actor,store,c.month(),null,null,null,100,0);}
